/**
 * Principia Metaphysica - Paths page (classic script).
 *
 * Draws the lineage and switches views from the precomputed integer layout in
 * AutoGenerated/path_graph.json (no client-side layout), with pan/zoom, an inspector
 * and a path list.  Reads: path_graph.json, paths/index.json, paths/<id>/summary.json.
 * All catalogue text is inserted with textContent (never parsed as markup).  D-021 governs
 * the wording: off-path values are never presented as predictions.
 */
(function () {
  'use strict';

  var DATA = '../AutoGenerated/';
  var SVGNS = 'http://www.w3.org/2000/svg';
  var GOLD = '#ffd93d';
  var FALLBACK = { trunk: '#9aa0b4', branch: '#4fc3f7', dead_end: '#5c5c6b', active: GOLD, decision: '#c792ea', theory: '#f8f9fa' };
  var MIN_SCALE = 0.45;            // lineage nodes (200 units wide) stay about 90 px wide or more
  var DECLARED = 'Declared, not computed';
  var DECIDED_COLOR = '#c792ea', EXCLUDES_COLOR = '#ff6b6b';
  var DECLARED_REASON = 'Declared in the theory, but no path was computed for this option.';
  var NOT_PREDICTION = 'These are this path’s results, not the theory’s predictions.';

  var G = window.PMPathsGlow;
  var SWITCH_TYPES = { fork: 1, option: 1, decision: 1, theory: 1 };
  var S = { graph: null, index: null, view: 'lineage', nodes: {}, sel: null, vb: null, box: null, summaries: {}, token: 0 };

  // ---------- DOM helpers ----------

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = String(text);
    return e;
  }

  function sv(tag, attrs, text) {
    var e = document.createElementNS(SVGNS, tag);
    Object.keys(attrs || {}).forEach(function (k) { e.setAttribute(k, attrs[k]); });
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function add(parent) {
    for (var i = 1; i < arguments.length; i++) if (arguments[i]) parent.appendChild(arguments[i]);
    return parent;
  }

  function fetchJson(url) {
    return fetch(url).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status + ' for ' + url);
      return r.json();
    });
  }

  function colorFor(cls) {
    var legend = (S.graph && S.graph.legend) || {};
    if (legend[cls] && legend[cls].color) return legend[cls].color;
    return FALLBACK[cls] || '#8a8a99';
  }

  function trunc(text, w) {
    var max = Math.max(4, Math.floor(w / 7));
    return text.length > max ? text.slice(0, max - 1) + '…' : text;
  }

  function optionPathId(node) {
    var a = node.attrs || {};
    var m = /^option:([^.]+)\.(.+)$/.exec(node.id);
    return m ? (a.fork || m[1]) + '--' + m[2] : null;
  }

  function pathEntry(id) {
    var list = (S.index && S.index.paths) || [];
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }

  function notComputed(id) {
    var list = (S.index && S.index.not_computed) || [];
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }

  // ---------- graph model ----------

  function indexNodes() {
    S.nodes = {};
    S.graph.nodes.forEach(function (n) { S.nodes[n.id] = n; });
  }

  function goldAncestry() {
    var parents = {};
    S.graph.edges.forEach(function (e) { if (e.type === 'evolves_to') parents[e.target] = e.source; });
    var gold = {};
    var active = S.graph.nodes.filter(function (n) { return n.type === 'version' && n.status === 'active'; })[0];
    for (var id = active && active.id; id && !gold[id]; id = parents[id]) gold[id] = true;
    return gold;
  }

  function lineageBox() {
    var L = S.graph.layout.lineage;
    return L && L.bbox ? L.bbox.slice() : [0, 0, 800, 400];
  }

  function switchesBox() {
    return (S.graph.layout.bbox || [0, 0, 800, 400]).slice();
  }

  // ---------- drawing ----------

  function nodeGroup(n, pos, gold, kind) {
    var cls = n.class || n.status || '';
    var isGold = gold || cls === 'active';
    var g = sv('g', { 'class': 'pp-node' + (kind === 'option' ? G.glowClass(n) : ''), tabindex: '0', role: 'button', 'data-id': n.id,
      'aria-label': n.label + (n.status ? ' (' + n.status + ')' : ''),
      transform: 'translate(' + pos[0] + ',' + pos[1] + ')' });
    g.appendChild(sv('title', {}, n.label));
    g.appendChild(sv('rect', { width: pos[2], height: pos[3], rx: 6, fill: '#12162f',
      stroke: isGold ? GOLD : colorFor(cls), 'stroke-width': isGold ? 3 : 2,
      'stroke-dasharray': cls === 'not_implemented' ? '5 3' : '' }));
    g.appendChild(sv('text', { x: 8, y: pos[3] / 2 + 4, fill: '#f8f9fa', 'font-size': 12 }, trunc(n.label, pos[2] - 8)));
    g.__kind = kind;
    return g;
  }

  function drawEdge(layer, a, b, color, dashed, width) {
    layer.appendChild(sv('line', { x1: a[0] + a[2] / 2, y1: a[1] + a[3] / 2, x2: b[0] + b[2] / 2,
      y2: b[1] + b[3] / 2, stroke: color, 'stroke-width': width || 2,
      'stroke-dasharray': dashed ? '6 4' : '' }));
  }

  function drawLineage(svg) {
    var L = S.graph.layout.lineage || { positions: {}, eras: [], lanes: [] };
    var gold = goldAncestry();
    var edges = sv('g'), nodes = sv('g'), axes = sv('g');
    L.eras.forEach(function (e) {
      axes.appendChild(sv('line', { x1: e.x, y1: 0, x2: e.x, y2: L.bbox[3], stroke: '#2a2f4a', 'stroke-dasharray': '2 4' }));
      axes.appendChild(sv('text', { x: e.x + 4, y: 14, fill: '#adb5bd', 'font-size': 12 }, e.label));
    });
    L.lanes.forEach(function (l) {
      axes.appendChild(sv('text', { x: 4, y: l.y - 6, fill: '#6c757d', 'font-size': 11 }, l.label));
    });
    S.graph.edges.forEach(function (e) {
      var a = L.positions[e.source], b = L.positions[e.target];
      if (!a || !b || (e.type !== 'evolves_to' && e.type !== 'superseded_by')) return;
      var g = gold[e.source] && gold[e.target] && e.type === 'evolves_to';
      drawEdge(edges, a, b, g ? GOLD : colorFor(e.class), e.type === 'superseded_by', g ? 4 : 2);
    });
    S.graph.nodes.forEach(function (n) {
      if (n.type === 'version' && L.positions[n.id]) nodes.appendChild(nodeGroup(n, L.positions[n.id], !!gold[n.id], 'version'));
    });
    add(svg, axes, edges, nodes);
  }

  function activeOptionPolyline(layer, pos) {
    var pts = [];
    var cols = S.graph.layout.columns || [];
    cols.forEach(function (c) {
      var opt = S.graph.nodes.filter(function (n) {
        return n.type === 'option' && n.attrs && n.attrs.fork === c.fork && n.attrs.on_active_path && pos[n.id];
      })[0];
      if (opt) pts.push((pos[opt.id][0] + pos[opt.id][2] / 2) + ',' + (pos[opt.id][1] + pos[opt.id][3] / 2));
    });
    if (pts.length > 1) layer.appendChild(sv('polyline', { points: pts.join(' '), fill: 'none', stroke: GOLD, 'stroke-width': 4, opacity: 0.8 }));
  }

  // Edges along reasonable alternative paths glow in the reasonable colour (never gold).
  function reasonableEdges(layer, pos) {
    S.graph.edges.forEach(function (e) {
      if (e.type !== 'path_step' || e.class !== 'reasonable' || !pos[e.source] || !pos[e.target]) return;
      var a = pos[e.source], b = pos[e.target];
      layer.appendChild(sv('line', { 'class': 'pp-reasonable-edge', x1: a[0] + a[2] / 2, y1: a[1] + a[3] / 2,
        x2: b[0] + b[2] / 2, y2: b[1] + b[3] / 2, 'stroke-width': 3 }));
    });
  }

  // Decided-by and excludes links between forks, options and decisions (thin, dashed).
  function drawRuleEdges(layer, pos) {
    S.graph.edges.forEach(function (e) {
      if ((e.type !== 'decided_by' && e.type !== 'excludes') || !pos[e.source] || !pos[e.target]) return;
      var dec = e.type === 'decided_by';
      var line = sv('g', { 'class': dec ? 'pp-edge-decided' : 'pp-edge-excludes', opacity: 0.55 });
      drawEdge(line, pos[e.source], pos[e.target], dec ? DECIDED_COLOR : EXCLUDES_COLOR, true, 1);
      layer.appendChild(line);
    });
  }

  function drawSwitches(svg) {
    var pos = S.graph.layout.positions || {};
    var edges = sv('g'), nodes = sv('g');
    S.graph.edges.forEach(function (e) {
      if (e.type === 'has_option' && pos[e.source] && pos[e.target]) drawEdge(edges, pos[e.source], pos[e.target], colorFor(e.class), false, 1.5);
    });
    drawRuleEdges(edges, pos);
    reasonableEdges(edges, pos);
    activeOptionPolyline(edges, pos);
    S.graph.nodes.forEach(function (n) {
      if (SWITCH_TYPES[n.type] && pos[n.id]) {
        nodes.appendChild(nodeGroup(n, pos[n.id], !!(n.attrs && n.attrs.on_active_path), n.type));
      }
    });
    add(svg, edges, nodes);
  }

  function renderLegend() {
    var box = document.getElementById('pp-legend');
    if (!box) return;
    box.textContent = '';
    var L = (S.graph && S.graph.legend) || {};
    ['active', 'reasonable'].forEach(function (k) {
      var li = el('li', 'pp-key pp-key-' + k);
      add(li, el('span', 'pp-swatch'), el('span', '', (L[k] && L[k].label) || (k === 'reasonable' ? 'Reasonable alternative' : k)));
      box.appendChild(li);
    });
    [['decided', 'Decided by (decision link)'], ['excludes', 'Excludes']].forEach(function (k) {
      add(box, add(el('li', 'pp-key pp-key-' + k[0]), el('span', 'pp-swatch'), el('span', '', k[1])));
    });
    if (!hasReasonable()) box.appendChild(el('li', 'pp-key pp-key-none', reasonableNote()));
  }

  function hasReasonable() {
    return S.graph.nodes.some(function (n) { return G.isReasonable(n); });
  }

  // Why the reasonable glow is absent, with the rule stated from the ranking block.
  function reasonableNote() {
    var rule = S.graph.ranking && S.graph.ranking.reasonable_rule;
    return 'No alternative currently meets the rule for a reasonable alternative (' +
      (rule || 'rule not available in this build') + ').';
  }

  function setViewBox() {
    var v = S.vb;
    S.svg.setAttribute('viewBox', [v.x, v.y, v.w, v.h].join(' '));
  }

  function fitAll() {
    var b = S.box, pad = 20;
    return { x: b[0] - pad, y: b[1] - pad, w: b[2] - b[0] + 2 * pad, h: b[3] - b[1] + 2 * pad };
  }

  // Lineage: never smaller than MIN_SCALE, and centred on the active version when it does not all fit.
  function fitLineage() {
    var all = fitAll(), r = S.svg.getBoundingClientRect();
    if (!r.width || !r.height || r.width / all.w >= MIN_SCALE) return all;
    var w = r.width / MIN_SCALE, h = r.height / MIN_SCALE;
    var pos = (S.graph.layout.lineage.positions || {})[activeVersionId()];
    var cx = pos ? pos[0] + pos[2] / 2 : all.x + w / 2;
    var x = Math.min(Math.max(cx - w / 2, all.x), all.x + all.w - w);
    var y = h >= all.h ? all.y - (h - all.h) / 2 : all.y;
    return { x: x, y: y, w: w, h: h };
  }

  function activeVersionId() {
    var a = S.graph.nodes.filter(function (n) { return n.type === 'version' && n.status === 'active'; })[0];
    return a && a.id;
  }

  function resetView() {
    S.vb = S.view === 'lineage' ? fitLineage() : fitAll();
    setViewBox();
  }

  function drawGraph() {
    var svg = S.svg;
    while (svg.firstChild) svg.removeChild(svg.firstChild);
    S.box = S.view === 'lineage' ? lineageBox() : switchesBox();
    if (S.view === 'lineage') drawLineage(svg); else drawSwitches(svg);
    resetView();
    markSelected();
  }

  // Node ids the current selection stands for; 'path:main' means the active version and the active-path options.
  function selectionTargets() {
    if (S.sel === 'path:main') {
      var ids = S.graph.nodes.filter(function (n) { return n.attrs && n.attrs.on_active_path && n.type === 'option'; })
        .map(function (n) { return n.id; });
      return [activeVersionId()].concat(ids).filter(Boolean);
    }
    return S.nodes[S.sel] ? [S.sel] : [];
  }

  function drawnIds() {
    var out = {};
    Array.prototype.forEach.call(S.svg.querySelectorAll('.pp-node'), function (g) { out[g.getAttribute('data-id')] = g; });
    return out;
  }

  // Nearest drawn ancestor (maps_to, has_option, evolves_to parents), breadth first, a few levels up.
  function nearestDrawnAncestor(id, drawn) {
    var seen = {}, level = [id];
    for (var d = 0; d < 4 && level.length; d++) {
      var next = [];
      level.forEach(function (cur) {
        S.graph.edges.forEach(function (e) {
          if (e.target === cur && (e.type === 'maps_to' || e.type === 'has_option' || e.type === 'evolves_to') && !seen[e.source]) {
            seen[e.source] = true; next.push(e.source);
          }
        });
      });
      for (var i = 0; i < next.length; i++) if (drawn[next[i]]) return next[i];
      level = next;
    }
    return null;
  }

  function showViewNote(text) {
    var n = document.getElementById('pp-viewnote');
    if (n) n.textContent = text;
  }

  // Highlight the selection in this view; fall back to the nearest ancestor and say so.
  function markSelected() {
    var drawn = drawnIds(), targets = selectionTargets();
    var hit = targets.filter(function (id) { return drawn[id]; });
    var anc = !hit.length && targets.length ? nearestDrawnAncestor(targets[0], drawn) : null;
    Object.keys(drawn).forEach(function (id) {
      drawn[id].classList.toggle('is-selected', hit.indexOf(id) >= 0);
      drawn[id].classList.toggle('is-ancestor', id === anc);
    });
    var label = targets.length && S.nodes[targets[0]] ? S.nodes[targets[0]].label : '';
    if (hit.length || !targets.length) showViewNote('');
    else showViewNote(label + ' is not drawn in this view' + (anc ? '; showing its nearest ancestor, ' + S.nodes[anc].label + '.' : '.'));
  }

  // ---------- pan and zoom ----------

  function zoom(factor, cx, cy) {
    var v = S.vb;
    var px = cx === undefined ? v.x + v.w / 2 : cx;
    var py = cy === undefined ? v.y + v.h / 2 : cy;
    var nw = Math.min(Math.max(v.w * factor, 60), 20000);
    var k = nw / v.w;
    S.vb = { x: px - (px - v.x) * k, y: py - (py - v.y) * k, w: nw, h: v.h * k };
    setViewBox();
  }

  function clientToSvg(ev) {
    var r = S.svg.getBoundingClientRect();
    return { x: S.vb.x + (ev.clientX - r.left) / r.width * S.vb.w, y: S.vb.y + (ev.clientY - r.top) / r.height * S.vb.h,
      sx: S.vb.w / r.width, sy: S.vb.h / r.height };
  }

  function wirePanZoom() {
    var svg = S.svg, drag = null;
    svg.addEventListener('wheel', function (ev) {
      ev.preventDefault();
      var p = clientToSvg(ev);
      zoom(ev.deltaY > 0 ? 1.15 : 1 / 1.15, p.x, p.y);
    }, { passive: false });
    svg.addEventListener('pointerdown', function (ev) {
      drag = { x: ev.clientX, y: ev.clientY, moved: false };
    });
    svg.addEventListener('pointermove', function (ev) {
      if (!drag) return;
      var p = clientToSvg(ev);
      var dx = ev.clientX - drag.x, dy = ev.clientY - drag.y;
      if (Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
      if (!drag.moved) return;
      S.vb.x -= dx * p.sx; S.vb.y -= dy * p.sy;
      drag.x = ev.clientX; drag.y = ev.clientY;
      setViewBox();
    });
    svg.addEventListener('pointerup', function () { setTimeout(function () { drag = null; }, 0); });
    svg.addEventListener('click', function (ev) {
      var g = ev.target.closest && ev.target.closest('.pp-node');
      if (g && !(drag && drag.moved)) selectNode(g.getAttribute('data-id'));
    });
    svg.addEventListener('keydown', onKey);
  }

  function onKey(ev) {
    var step = S.vb.w * 0.08;
    var g = ev.target.closest && ev.target.closest('.pp-node');
    if ((ev.key === 'Enter' || ev.key === ' ') && g) { ev.preventDefault(); selectNode(g.getAttribute('data-id')); return; }
    var moves = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
    if (moves[ev.key]) { ev.preventDefault(); S.vb.x += moves[ev.key][0]; S.vb.y += moves[ev.key][1]; setViewBox(); }
    else if (ev.key === '+' || ev.key === '=') zoom(1 / 1.25);
    else if (ev.key === '-') zoom(1.25);
    else if (ev.key === '0') resetView();
  }

  // ---------- inspector ----------

  function section(title) {
    var s = el('section', 'pp-sec');
    s.appendChild(el('h3', '', title));
    return s;
  }

  function listSec(title, items) {
    if (!items || !items.length) return null;
    var s = section(title), ul = el('ul');
    items.forEach(function (t) { ul.appendChild(el('li', '', t)); });
    return add(s, ul);
  }

  function textSec(title, text) {
    return text ? add(section(title), el('p', '', text)) : null;
  }

  function resultsRows(items) {
    var ul = el('ul', 'pp-kv');
    items.forEach(function (kv) {
      if (kv[1] === null || kv[1] === undefined || kv[1] === '') return;
      var li = el('li');
      add(li, el('strong', '', kv[0] + ': '), document.createTextNode(String(kv[1])));
      ul.appendChild(li);
    });
    return ul;
  }

  function versionSections(n) {
    var a = n.attrs || {};
    var s = [el('p', 'pp-tag', 'Archival: not re-run'), textSec('Framing', a.framing), textSec('Why', a.why),
      listSec('What worked', a.worked), listSec('What failed', a.failed)];
    if (a.key_results && a.key_results.length) {
      var sec = section('Key results'), ul = el('ul');
      a.key_results.forEach(function (k) {
        ul.appendChild(el('li', '', k.quantity + ' = ' + k.value + '  [source: ' + (k.source || 'none given') + ']'));
      });
      s.push(add(sec, ul));
    }
    s.push(listSec('Evidence', a.evidence), listSec('Maps to options', a.maps_to));
    return s;
  }

  function optionSections(n) {
    var a = n.attrs || {}, r = n.rationale || {};
    var s = [textSec('Summary', a.summary || r.summary), textSec('Consequence', a.consequence)];
    (r.sections || []).forEach(function (sec) {
      s.push(textSec((sec.heading || sec.key || '').replace(/:$/, ''), sec.body));
    });
    var meta = resultsRows([['Status', n.status || n.class], ['Decision refs', (a.decision_refs || []).join(', ')],
      ['Kill condition', a.kill_condition], ['Restored from', a.restored_from]]);
    s.push(add(section('Record'), meta));
    if (a.on_active_path) s.push(el('p', 'pp-tag', 'On the main path.'));
    s.push(listSec('Decided by', linkedLabels(n.id, 'decided_by', false)), listSec('Excludes', linkedLabels(n.id, 'excludes', false)),
      listSec('Excluded by', linkedLabels(n.id, 'excludes', true)));
    var rows = G.inspectorRows(n, S.graph.ranking);
    if (rows.length) s.push(add(section('Reasonable alternative'), resultsRows(rows)));
    if (a.implemented === false || n.class === 'not_implemented') s.push(el('p', 'pp-tag', 'Not implemented: declared only, nothing is runnable yet.'));
    return s;
  }

  function linkedLabels(id, type, from) {
    return S.graph.edges.filter(function (e) { return e.type === type && e[from ? 'target' : 'source'] === id; })
      .map(function (e) { var o = S.nodes[e[from ? 'source' : 'target']]; return o ? o.label : e[from ? 'source' : 'target']; });
  }

  function decisionSections(n) {
    var a = n.attrs || {};
    var rows = resultsRows([['Status', n.status], ['Date', a.date], ['Title', a.title], ['In decision log', a.in_log === undefined ? null : String(a.in_log)]]);
    return [textSec('Summary', a.summary), add(section('Record'), rows),
      listSec('Decides', linkedLabels(n.id, 'decided_by', true)),
      listSec('Log entries', (a.entries || []).map(function (x) { return x.heading; }))];
  }

  function theorySections(n) {
    var a = n.attrs || {};
    return [add(section('Record'), resultsRows([['Status', n.status], ['Theory', a.theory], ['Forks', a.n_forks],
      ['Options', a.n_options], ['Constraints', a.n_constraints]]))];
  }

  function forkSections(n) {
    var r = n.rationale || {};
    return [textSec('Question', (n.attrs && n.attrs.question) || r.summary)];
  }

  function entrySections(e) {
    return [textSec('Why', e.why), textSec('Summary', e.summary), textSec('Consequence', e.consequence),
      textSec('Question', e.deviation && e.deviation.question), listSec('Decision refs', e.decision_refs)];
  }

  function renderInspector(node, entry, notRun) {
    var box = S.inspector;
    S.token += 1;
    while (box.firstChild) box.removeChild(box.firstChild);
    var title = node ? node.label : (entry ? entry.label : 'Select a node or a path');
    box.appendChild(el('h2', '', title));
    var parts = [];
    if (node && node.type === 'version') parts = versionSections(node);
    else if (node && node.type === 'option') parts = optionSections(node);
    else if (node && node.type === 'fork') parts = forkSections(node).concat([listSec('Decided by', linkedLabels(node.id, 'decided_by', false))]);
    else if (node && node.type === 'decision') parts = decisionSections(node);
    else if (node && node.type === 'theory') parts = theorySections(node);
    else if (entry) parts = entrySections(entry);
    else parts = [el('p', 'pp-hint', 'Choose a version, an option or a path from the list to read why it was kept, rejected or considered.')];
    parts.forEach(function (p) { if (p) box.appendChild(p); });
    if (entry && node && node.type === 'option') entrySections(entry).slice(0, 1).forEach(function (p) { if (p) box.appendChild(p); });
    if (notRun) box.appendChild(add(section('Not computed'), el('p', '', notRun.reason || 'no reason recorded')));
    if (entry) renderResults(box, entry);
  }

  // ---------- results panel ----------

  function pathButtons(entry) {
    var row = el('div', 'pp-actions');
    var view = el('a', 'pp-btn', 'View this path across the site');
    view.href = 'parameters.html?path=' + encodeURIComponent(entry.id);
    var back = el('button', 'pp-btn pp-btn-secondary', 'Return to main path');
    back.type = 'button';
    back.addEventListener('click', function () { if (window.PMPath) window.PMPath.returnToMain(); });
    if (entry.id !== 'main' && entry.computed) row.appendChild(view);
    row.appendChild(back);
    return row;
  }

  function scoreText(sb) {
    return sb ? Object.keys(sb).map(function (k) { return k + ' ' + sb[k]; }).join(', ') : null;
  }

  function compareRows(sum, main) {
    var t = el('table', 'pp-table');
    var head = el('tr');
    ['', 'This path', 'Main'].forEach(function (h) { head.appendChild(el('th', '', h)); });
    t.appendChild(head);
    var m = main || {};
    var rows = [
      ['Scoreboard', scoreText(sum.scoreboard), scoreText(m.scoreboard)],
      ['chi-squared (per-path summary.json, not the ranking chi-squared)', sum.chi2 ? sum.chi2.value + ' (dof ' + sum.chi2.dof + ')' : null, m.chi2 ? m.chi2.value + ' (dof ' + m.chi2.dof + ')' : null],
      ['Generations', sum.n_gen ? sum.n_gen.value + ' / target ' + sum.n_gen.target + (sum.n_gen.holds ? ' (holds)' : ' (does not hold)') : null,
        m.n_gen ? m.n_gen.value + ' / target ' + m.n_gen.target : null],
      ['Gates passed', gateText(sum.gates), gateText(m.gates)],
      ['Certificate claims holding', certText(sum.certificate), certText(m.certificate)]
    ];
    rows.forEach(function (r) {
      if (r[1] === null && r[2] === null) return;
      var tr = el('tr');
      r.forEach(function (c, i) { tr.appendChild(el(i ? 'td' : 'th', '', c === null ? 'n/a' : c)); });
      t.appendChild(tr);
    });
    return t;
  }

  function gateText(g) {
    return g ? g.filter(function (x) { return x.passed; }).length + ' / ' + g.length : null;
  }

  function certText(c) {
    return c ? c.filter(function (x) { return x.holds; }).length + ' / ' + c.length : null;
  }

  function keyValuesTable(kv) {
    if (!kv || !kv.length) return null;
    var t = el('table', 'pp-table');
    var head = el('tr');
    ['Parameter', 'Value', 'Main', 'Experimental'].forEach(function (h) { head.appendChild(el('th', '', h)); });
    t.appendChild(head);
    kv.forEach(function (k) {
      var tr = el('tr');
      var name = (k.label || k.id) + (k.unit ? ' [' + k.unit + ']' : '') +
        (k.volatile ? ' (varies between builds of main; not this path’s result)' : '');
      [name, k.value, k.main, k.experimental].forEach(function (c) {
        tr.appendChild(el('td', '', c === null || c === undefined ? 'n/a' : c));
      });
      t.appendChild(tr);
    });
    return add(section('Key values (largest change first)'), t);
  }

  function fillResults(panel, entry, sum, main) {
    panel.appendChild(el('p', 'pp-notice', NOT_PREDICTION));
    if (sum.inert) {
      panel.appendChild(el('p', 'pp-tag', 'Inert: this switch is declared, but no simulation reads it yet, so its results equal main.'));
    }
    panel.appendChild(compareRows(sum, main));
    if (sum.changed) panel.appendChild(el('p', '', 'Changed values: ' + sum.changed.count));
    if (sum.unverified_files && sum.unverified_files.length) add(panel, listSec('Unverified files', sum.unverified_files));
    add(panel, keyValuesTable(sum.key_values));
  }

  function summaryFor(id) {
    if (!S.summaries[id]) S.summaries[id] = fetchJson(DATA + 'paths/' + id + '/summary.json').catch(function () { return null; });
    return S.summaries[id];
  }

  function renderResults(box, entry) {
    var panel = add(section('Results against main'), pathButtons(entry));
    box.appendChild(panel);
    var token = S.token;
    if (!entry.computed) {
      panel.appendChild(el('p', '', 'Not computed.'));
      return;
    }
    Promise.all([summaryFor(entry.id), summaryFor('main')]).then(function (r) {
      if (S.token !== token) return;
      if (!r[0]) panel.appendChild(el('p', '', 'The summary for this path could not be loaded.'));
      else fillResults(panel, entry, r[0], entry.id === 'main' ? null : r[1]);
    });
  }

  // ---------- selection ----------

  function entryIdForNode(n) {
    if (n.type === 'option') return optionPathId(n);
    if (n.type === 'version' && n.status === 'active') return 'main';
    return null;
  }

  // The reason text when an option has no computed path: recorded reason, else declared only.
  function notRunFor(pid) {
    if (!pid) return null;
    return notComputed(pid) || (pathEntry(pid) ? null : { reason: DECLARED_REASON });
  }

  function selectNode(id) {
    var n = S.nodes[id];
    if (!n) return;
    S.sel = id;
    var pid = entryIdForNode(n);
    var onActive = n.type === 'option' && n.attrs && n.attrs.on_active_path;
    var entry = pid ? pathEntry(onActive ? 'main' : pid) : null;
    if (pid && history.replaceState) history.replaceState(null, '', '#' + pid);
    renderInspector(n, entry && !onActive ? entry : null, onActive ? null : notRunFor(pid));
    markSelected();
    markList(onActive ? 'main' : pid);
  }

  function selectPath(id) {
    var entry = pathEntry(id), nc = notComputed(id);
    var node = null;
    Object.keys(S.nodes).forEach(function (k) { if (S.nodes[k].type === 'option' && optionPathId(S.nodes[k]) === id) node = S.nodes[k]; });
    if (!entry && !nc && !node) return;
    S.sel = node ? node.id : 'path:' + id;
    if (node && S.view !== 'switches') setView('switches');
    renderInspector(node, entry, nc || (node && !entry ? notRunFor(id) : null));
    markSelected();
    markList(id);
    if (history.replaceState) history.replaceState(null, '', '#' + id);
  }

  // ---------- path list ----------

  function markList(id) {
    Array.prototype.forEach.call(S.list.querySelectorAll('button'), function (b) {
      b.classList.toggle('is-selected', b.getAttribute('data-path') === id);
    });
  }

  function chipFor(p) {
    if (p.kind === 'main') return 'main';
    if (p.inert) return p.status + ', inert';
    return p.status + (p.changed_values ? ', ' + p.changed_values + ' changed' : '');
  }

  function listItem(id, label, chip, isMain, reason) {
    var li = el('li');
    var b = el('button', 'pp-item' + (isMain ? ' is-main' : ''));
    b.type = 'button';
    b.setAttribute('data-path', id);
    add(b, el('span', 'pp-item-label', label), el('span', 'pp-chip', chip), reason ? el('span', 'pp-item-reason', reason) : null);
    b.addEventListener('click', function () { selectPath(id); });
    li.appendChild(b);
    return li;
  }

  // Option nodes with neither a computed path nor a not-computed record.
  function declaredOnly() {
    return S.graph.nodes.filter(function (n) {
      var id = n.type === 'option' && optionPathId(n);
      return id && !pathEntry(id) && !notComputed(id);
    });
  }

  function groupPaths() {
    var groups = {};
    var glow = G.reasonableOptionKeys(S.graph && S.graph.nodes);
    ((S.index && S.index.paths) || []).forEach(function (p) {
      var g = p.kind === 'main' ? '(main)' : (p.deviation && p.deviation.fork) || 'other';
      (groups[g] = groups[g] || []).push({ id: p.id, label: p.label, chip: chipFor(p) + (glow[p.id] ? ', reasonable alternative' : ''), main: p.kind === 'main', text: [p.label, p.summary, p.why].join(' ') });
    });
    ((S.index && S.index.not_computed) || []).forEach(function (p) {
      var g = p.fork || 'other';
      (groups[g] = groups[g] || []).push({ id: p.id, label: p.fork + ' = ' + p.option, chip: 'not computed', main: false, reason: p.reason, text: p.id + ' ' + (p.reason || '') });
    });
    declaredOnly().forEach(function (n) {
      var id = optionPathId(n);
      (groups[DECLARED] = groups[DECLARED] || []).push({ id: id, label: ((n.attrs && n.attrs.fork) || '') + ' = ' + n.label,
        chip: 'declared only', main: false, reason: DECLARED_REASON, text: id + ' ' + DECLARED_REASON });
    });
    return groups;
  }

  function renderList(filter) {
    var q = (filter || '').toLowerCase();
    var groups = groupPaths();
    while (S.list.firstChild) S.list.removeChild(S.list.firstChild);
    Object.keys(groups).sort(function (a, b) { return (a === DECLARED) - (b === DECLARED) || (a < b ? -1 : a > b ? 1 : 0); }).forEach(function (g) {
      var items = groups[g].filter(function (i) { return !q || (i.id + ' ' + i.label + ' ' + i.text).toLowerCase().indexOf(q) >= 0; });
      if (!items.length) return;
      var li = el('li', 'pp-group'), ul = el('ul');
      li.appendChild(el('h3', '', g === '(main)' ? 'Main path' : g));
      items.forEach(function (i) { ul.appendChild(listItem(i.id, i.label, i.chip, i.main, i.reason)); });
      S.list.appendChild(add(li, ul));
    });
    if (!S.list.firstChild) S.list.appendChild(el('li', 'pp-hint', 'No paths match.'));
    markList(S.sel && S.sel.indexOf('path:') === 0 ? S.sel.slice(5) : null);
  }

  // ---------- header, toggle, boot ----------

  function setView(v) {
    S.view = v;
    Array.prototype.forEach.call(document.querySelectorAll('.pp-toggle button'), function (b) {
      b.setAttribute('aria-pressed', String(b.getAttribute('data-view') === v));
    });
    drawGraph();
  }

  function wireControls() {
    Array.prototype.forEach.call(document.querySelectorAll('.pp-toggle button'), function (b) {
      b.addEventListener('click', function () { setView(b.getAttribute('data-view')); });
    });
    document.getElementById('pp-zoom-in').addEventListener('click', function () { zoom(1 / 1.25); });
    document.getElementById('pp-zoom-out').addEventListener('click', function () { zoom(1.25); });
    document.getElementById('pp-zoom-reset').addEventListener('click', resetView);
    document.getElementById('pp-search').addEventListener('input', function (e) { renderList(e.target.value); });
    window.addEventListener('hashchange', applyHash);
  }

  function applyHash() {
    var id = decodeURIComponent(location.hash.replace(/^#/, ''));
    if (id) selectPath(id);
  }

  function showError(msg) {
    S.inspector.appendChild(el('p', 'pp-error', msg));
  }

  function boot() {
    S.svg = document.getElementById('pp-svg');
    S.inspector = document.getElementById('pp-inspector');
    S.list = document.getElementById('pp-list');
    wirePanZoom();
    wireControls();
    renderInspector(null, null, null);
    Promise.all([fetchJson(DATA + 'path_graph.json'), fetchJson(DATA + 'paths/index.json').catch(function () { return null; })])
      .then(function (r) {
        S.graph = r[0]; S.index = r[1];
        indexNodes();
        S.view = 'lineage';
        if (!(S.graph.layout && S.graph.layout.lineage)) S.view = 'switches';
        setView(S.view);
        renderLegend();
        renderList('');
        if (!S.index) showError('The path index (paths/index.json) is not published, so no path results are available.');
        applyHash();
      })
      .catch(function (err) { showError('The path graph could not be loaded: ' + err.message); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
